INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('52be2b1a-3c8b-4c91-87bd-741ea19c558a', NULL, 'system', 'notifications.insert', 'notifications', 'ea9c5c83-63e5-4ca4-8260-12136322fdeb', NULL, '{"id":"ea9c5c83-63e5-4ca4-8260-12136322fdeb","name":"Courier could not reach","event":"DELIVERY_FAILED","channel":"EMAIL","subject":"We could not deliver order {{ order.name }}","wa_body":null,"wa_name":null,"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>The courier could not reach you</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">{% if order.name %}Order {{ order.name }}{% endif %}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">The courier could not reach you</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, the courier tried to deliver your order {{ order.name }} but could not reach you.</p>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">To get it delivered, {% if shop.phone %}call us at {{ shop.phone }} or {% endif %}reply to this email.</p>\n</td></tr>\n{% if shipment.tracking_url or order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ shipment.tracking_url | default: order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Track your parcel</a>\n</td></tr>{% endif %}\n\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>","wa_params":null,"wa_reason":null,"wa_status":null,"conditions":[],"created_at":"2026-10-30T09:15:54.27243+00:00","is_enabled":false,"updated_at":"2026-10-30T09:15:54.27243+00:00","wa_buttons":false,"wa_version":0,"merchant_id":"00000000-0000-4000-8000-000000000001","wa_language":null,"reply_buttons":false,"wa_checked_at":null,"wa_template_id":null}', '{}', '2026-10-30T09:15:54.272Z', '00000000-0000-4000-8000-000000000001');
